<?php
$runs=all_runs($pdo);$runId=(int)($_GET['run']??0);$run=null;if($runId){$s=$pdo->prepare("SELECT * FROM riwayat_clustering WHERE id=? AND status='berhasil'");$s->execute([$runId]);$run=$s->fetch();}if(!$run)$run=latest_run($pdo);
$results=[];$counts=[];$centroids=[];$subjects=subjects($pdo);
if($run){$s=$pdo->prepare('SELECT h.*,m.kode_mahasiswa,m.angkatan FROM hasil_clustering h JOIN mahasiswa m ON m.id=h.mahasiswa_id WHERE h.riwayat_clustering_id=? ORDER BY h.nomor_cluster,m.kode_mahasiswa');$s->execute([$run['id']]);$results=$s->fetchAll();$s=$pdo->prepare('SELECT label_kompetensi,COUNT(*) jumlah FROM hasil_clustering WHERE riwayat_clustering_id=? GROUP BY label_kompetensi');$s->execute([$run['id']]);$counts=$s->fetchAll();$s=$pdo->prepare('SELECT c.*,mk.nama_mata_kuliah FROM centroid_clustering c JOIN mata_kuliah mk ON mk.id=c.mata_kuliah_id WHERE c.riwayat_clustering_id=? ORDER BY c.nomor_cluster,mk.id');$s->execute([$run['id']]);foreach($s as $c)$centroids[$c['nomor_cluster']][]=$c;}
$q=trim((string)($_GET['q']??''));$labelFilter=(string)($_GET['label']??'');$yearFilter=(int)($_GET['angkatan']??0);
$filtered=array_values(array_filter($results,function($r)use($q,$labelFilter,$yearFilter){return (!$q||stripos($r['kode_mahasiswa'],$q)!==false)&&(!$labelFilter||$r['label_kompetensi']===$labelFilter)&&(!$yearFilter||(int)$r['angkatan']===$yearFilter);}));
?>
<div class="page-heading"><div><div class="eyebrow">OUTPUT MODEL</div><h1>Hasil Clustering</h1><p>Hasil pengelompokan dan profil centroid dari riwayat yang dipilih.</p></div><?php if($run): ?><a class="btn btn-outline" href="<?= APP_BASE ?>/exports/hasil.csv.php?run=<?= (int)$run['id'] ?>">Ekspor CSV</a><?php endif; ?></div>
<?php if(!$run): ?><section class="panel"><div class="empty-state"><div class="empty-symbol">◎</div><h3>Belum ada hasil clustering</h3><p>Jalankan proses K-Means terlebih dahulu untuk melihat hasil pengelompokan.</p><a class="btn btn-primary" href="<?= url('clustering') ?>">Ke proses clustering</a></div></section>
<?php else: ?>
<div class="run-selector panel"><div><span class="muted small">RIWAYAT PROSES</span><strong><?= e($run['nama_proses']) ?></strong><span class="small muted"><?= e(date('d F Y, H:i',strtotime($run['created_at']))) ?> · <?= (int)$run['jumlah_data'] ?> data</span></div><form method="get"><input type="hidden" name="page" value="hasil-clustering"><select name="run" onchange="this.form.submit()"><?php foreach($runs as $r): if($r['status']!=='berhasil')continue; ?><option value="<?= (int)$r['id'] ?>" <?= (int)$run['id']===(int)$r['id']?'selected':'' ?>><?= e($r['nama_proses']) ?> (K=<?= (int)$r['jumlah_cluster'] ?>)</option><?php endforeach; ?></select></form></div>
<div class="stats-grid stats-three"><div class="stat-card"><div class="stat-top"><span>Data terkelompok</span><span class="stat-icon">N</span></div><div class="stat-number"><?= count($results) ?></div><div class="stat-foot">Dari data nilai lengkap</div></div><div class="stat-card"><div class="stat-top"><span>SSE</span><span class="stat-icon">Σ</span></div><div class="stat-number"><?= fmt((float)$run['sse'],3) ?></div><div class="stat-foot">Pada data terstandardisasi</div></div><div class="stat-card"><div class="stat-top"><span>Silhouette</span><span class="stat-icon">S</span></div><div class="stat-number"><?= $run['silhouette']===null?'—':fmt((float)$run['silhouette'],3) ?></div><div class="stat-foot">Rata-rata kualitas pemisahan</div></div></div>
<div class="content-grid"><section class="panel"><div class="panel-heading"><div><h2>Distribusi cluster</h2><p>Jumlah dan persentase mahasiswa per kategori</p></div></div><div class="chart-wrap chart-medium"><canvas id="clusterChart"></canvas></div><script type="application/json" id="clusterData"><?= json_encode(['labels'=>array_column($counts,'label_kompetensi'),'values'=>array_map('intval',array_column($counts,'jumlah'))]) ?></script></section><section class="panel"><div class="panel-heading"><div><h2>Interpretasi</h2><p>Label ditetapkan berdasarkan rata-rata centroid skala asli.</p></div></div><?php foreach($counts as $c): ?><div class="cluster-summary"><div><span class="legend-dot"></span><strong><?= e($c['label_kompetensi']) ?></strong></div><div><strong><?= (int)$c['jumlah'] ?></strong><span class="muted small">mahasiswa · <?= fmt(count($results)?100*$c['jumlah']/count($results):0,1) ?>%</span></div></div><?php endforeach; ?><p class="small muted mt-16">Kategori ini merangkum pola nilai pada dataset, bukan penilaian mutlak atas kemampuan individu.</p></section></div>
<section class="panel mt-24"><div class="panel-heading"><div><h2>Profil centroid</h2><p>Rata-rata nilai asli tiap atribut pada masing-masing cluster.</p></div></div><div class="table-scroll"><table><thead><tr><th>Mata kuliah</th><?php for($c=1;$c<=(int)$run['jumlah_cluster'];$c++): ?><th>Cluster <?= $c ?><br><small><?= e($centroids[$c][0]['nama_mata_kuliah']??'') ?></small></th><?php endfor; ?></tr></thead><tbody><?php foreach($subjects as $j=>$sub): ?><tr><td><?= e($sub['nama_mata_kuliah']) ?></td><?php for($c=1;$c<=(int)$run['jumlah_cluster'];$c++): ?><td><?= isset($centroids[$c][$j])?fmt((float)$centroids[$c][$j]['nilai_centroid'],2):'—' ?></td><?php endfor; ?></tr><?php endforeach; ?></tbody></table></div></section>
<section class="panel mt-24"><div class="panel-heading"><div><h2>Daftar hasil pengelompokan</h2><p><?= count($filtered) ?> dari <?= count($results) ?> mahasiswa</p></div><form method="get" class="filter-form"><input type="hidden" name="page" value="hasil-clustering"><input type="hidden" name="run" value="<?= (int)$run['id'] ?>"><input name="q" placeholder="Cari kode" value="<?= e($q) ?>"><select name="label"><option value="">Semua kategori</option><?php foreach(['Kompetensi Perlu Ditingkatkan','Kompetensi Menengah','Kompetensi Tinggi'] as $l): ?><option <?= $labelFilter===$l?'selected':'' ?>><?= e($l) ?></option><?php endforeach; ?></select><select name="angkatan"><option value="0">Semua angkatan</option><?php foreach([2024,2025,2026] as $y): ?><option value="<?= $y ?>" <?= $yearFilter===$y?'selected':'' ?>><?= $y ?></option><?php endforeach; ?></select><button class="btn btn-outline">Filter</button></form></div><div class="table-scroll"><table><thead><tr><th>No.</th><th>Kode mahasiswa</th><th>Angkatan</th><th>Nomor cluster</th><th>Label kompetensi</th></tr></thead><tbody><?php foreach($filtered as $i=>$r): ?><tr><td><?= $i+1 ?></td><td><strong><?= e($r['kode_mahasiswa']) ?></strong></td><td><?= (int)$r['angkatan'] ?></td><td>Cluster <?= (int)$r['nomor_cluster'] ?></td><td><span class="pill <?= str_contains($r['label_kompetensi'],'Tinggi')?'pill-success':(str_contains($r['label_kompetensi'],'Menengah')?'pill-info':'pill-warning') ?>"><?= e($r['label_kompetensi']) ?></span></td></tr><?php endforeach; if(!$filtered): ?><tr><td colspan="5"><div class="empty-inline">Tidak ada hasil yang sesuai filter.</div></td></tr><?php endif; ?></tbody></table></div></section>
<?php endif; ?>
